import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,a as o}from"./chunks/M-S-LCS15b3.Bke3gG24.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as r,o as n,c as l,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Autres options diverses","description":"","frontmatter":{"source_hash":"87f439d0b6","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/misc.md","filePath":"fr/use/misc.md"}'),u={name:"fr/use/misc.md"};function d(c,s,m,h,b,g){return n(),l("div",null,[...s[0]||(s[0]=[p('<p>D&#39;autres options sont disponibles dans ce menu.<br> Si elles sont cachées ici, c&#39;est sans doute parce que vous n&#39;aurez pas besoin de les modifier tous les jours, ou que vous devriez les laisser telles quelles sauf indication contraire.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>   Paramètres moins courants<br>    Autres options diverses</p></div><h5 id="run-collector-in-foreground" tabindex="-1">Exécutez Collector au premier plan <a class="header-anchor" href="#run-collector-in-foreground" aria-label="Permalink to &quot;Exécutez Collector au premier plan {#run-collector-in-foreground}&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Depuis l&#39;abandon de la prise en charge d&#39;Android 7 (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 juil. 2026</a>), ce n&#39;est plus une option que vous pouvez désactiver.</p></div><p>Sous Android 8.0 et plus (version minimale prise en charge), xDrip exécute toujours son collecteur en tant que service au premier plan pour éviter qu&#39;Android ne le mette en veille. Un graphique de notification persistante est donc toujours affiché, visible sur l&#39;écran de verrouillage.</p><p>Si vous préférez ne pas afficher le graphique, l&#39;option <code>Notification persistante compacte</code> du même menu n&#39;affiche que la glycémie actuelle.</p><div class="admonition xdripitem"><p class="admonition-title">Notification persistante compacte <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Activer pour masquer le graphique dans la notification et afficher uniquement la valeur de glucose actuelle.</p></div><img src="'+t+'" style="zoom:75%;"><h5 id="engineering-mode" tabindex="-1">Mode développeur <a class="header-anchor" href="#engineering-mode" aria-label="Permalink to &quot;Mode développeur {#engineering-mode}&quot;">​</a></h5><p>Active des fonctions potentiellement dangereuses ou non testées. Il n&#39;est pas nécessaire de l&#39;activer pour redémarrer un émetteur G5 ou un ancien émetteur G6 (les nouveaux, appelés Firefly, ne peuvent pas être redémarrés). En pratique, vous n&#39;avez pas besoin de l&#39;activer.</p><div class="admonition xdripitem"><p class="admonition-title">Mode développeur <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Permet de changer les paramètres les plus dangereux qui pourraient tout casser !</p></div><p>Pour activer l&#39;Engineering mode, saisissez ou prononcez le traitement <code>enable engineering mode</code>.</p><p>Un rappel mensuel vous signalera que l&#39;Engineering mode est activé. Assurez-vous d&#39;en avoir vraiment besoin, sinon laissez-le désactivé.</p><img src="'+o+'" style="zoom:52%;"><h5 id="battery-optimization-prompt" tabindex="-1">Invité pour l’optimisation de la batterie <a class="header-anchor" href="#battery-optimization-prompt" aria-label="Permalink to &quot;Invité pour l’optimisation de la batterie {#battery-optimization-prompt}&quot;">​</a></h5><p>Doit rester <strong>désactivé</strong>. xDrip doit être <a href="./../install/install.html#authorize-background-activity">exclu de l&#39;optimisation de la batterie</a> et ne doit pas y être soumis.</p><div class="admonition xdripitem"><p class="admonition-title">Invité pour l’optimisation de la batterie <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Sur Android 6+ s&#39;assurer que l&#39;optimisation de la batterie est désactivée (recommandé).</p></div><h5 id="samsung-workarounds" tabindex="-1">Samsung Workarounds <a class="header-anchor" href="#samsung-workarounds" aria-label="Permalink to &quot;Samsung Workarounds {#samsung-workarounds}&quot;">​</a></h5><p>Renommé en Solutions de contournement Wake, car d&#39;autres appareils ne sont pas conformes.</p><h5 id="wake-workarounds" tabindex="-1">Solutions de contournement Wake <a class="header-anchor" href="#wake-workarounds" aria-label="Permalink to &quot;Solutions de contournement Wake {#wake-workarounds}&quot;">​</a></h5><p>Corrige une non-conformité de certains appareils Android ; activé désormais par défaut pour Samsung, Xiaomi, OnePlus, Oppo et Huawei.<br> Doit rester <strong>activé</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Solutions de contournement Wake <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Utiliser des contournements pour éviter le comportement Android non standard de certains terminaux. Sans cela, les collecteurs ne peuvent pas obtenir les données.</p></div><p>Utilisation Wakelocks excessive n&#39;est pas nécessaire. Il s&#39;agit de messages de &quot;réveil&quot; supplémentaires envoyés par xDrip à votre appareil Android pour l&#39;empêcher de passer en mode veille.</p><div class="admonition xdripitem"><p class="admonition-title">Utilisation Wakelocks excessive <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p>Wakelocks anciennes qui peuvent drainer la batterie, mais pourraient être nécessaires pour NightWatch ou Android Wear</p></div><p>Afficher les valeurs prédictives (ancienne méthode) est obsolète. Utilisez la <a href="./predictions.html">simulation prédictive</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les valeurs prédictives <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Vieille méthode - non recommandée ! Tente de prédire les lectures chaque minute basé sur les valeurs passées récentes.</p></div><p>Proper Ongoing est indispensable pour les appareils sous Android 8 et plus. Visible uniquement lorsque l&#39;Engineering mode (Mode développeur) est activé.</p><div class="admonition xdripitem"><p class="admonition-title">Proper Ongoing <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Use proper ongoing notification. Disabling this causes collector problems on Android 8+ (utiliser une notification permanente correcte ; la désactiver cause des problèmes de collecteur sous Android 8+)</p></div><h5 id="out-of-process-algorithm" tabindex="-1">Algorithme hors processus <a class="header-anchor" href="#out-of-process-algorithm" aria-label="Permalink to &quot;Algorithme hors processus {#out-of-process-algorithm}&quot;">​</a></h5><p>L&#39;<a href="./OOP.html">algorithme hors processus</a> (Out Of Process Algorithm) permet d&#39;intégrer un plugin externe qui fournit des glycémies semblables à celles du fabricant pour les capteurs Libre, ou qui décode les informations du capteur Libre 2 EU.<br> Si l&#39;application externe n&#39;est pas présente sur votre téléphone ou ne fournit pas les informations, xDrip n&#39;affichera pas de glycémie.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>Cette option ne doit être activée que si vous utilisez un algorithme hors processus de version 1 (OOP1).<br> Elle doit être désactivée pour OOP2.</p></div><div class="admonition xdripitem"><p class="admonition-title">Algorithme Libre hors processus. <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser un algorithme Libre hors processus.(BluCon/NFC/LibreAlarm)</p></div><h5 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2 {#oop2}&quot;">​</a></h5><p>OOP2 est indispensable pour traiter les données des Libre 14 jours US et Libre 2/2+ EU.</p><div class="admonition xdripitem"><p class="admonition-title">Calibration par algorithme OOP2.</p><p> Appliquer les méthodes de calibration xDrip sur des données OOP.</p></div><p>Vous pouvez utiliser OOP2 de différentes façons :</p><ul><li>No calibration génère des valeurs semblables à celles du fabricant (mode natif) sans avoir besoin d&#39;étalonner. Cela ne signifie pas que les résultats sont non étalonnés (bruts) : un algorithme semblable à celui du fabricant est appliqué (comme le lecteur Libre 1).</li><li>Calibrate based on raw utilise les données brutes du capteur (sans correction de température), comme le Libre 1. Vous utiliserez l&#39;algorithme d&#39;étalonnage de xDrip. <strong>Réglage par défaut.</strong></li><li>Calibrate based on glucose vous permet d&#39;appliquer l&#39;étalonnage xDrip aux valeurs natives. Les données brutes sont transformées par l&#39;algorithme semblable à celui du fabricant, puis transmises à l&#39;algorithme d&#39;étalonnage de xDrip.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Calibration par algorithme OOP2.</p><p> No calibration       ○<br>  Calibrate based on raw   ●<br>  Calibrate based on glucose (experimental)  ○</p></div><p>Lissage des données Libre fait la moyenne sur 5 mesures. Cela retarde aussi les valeurs.<br> Si cette option n&#39;apporte pas l&#39;amélioration attendue, essayez aussi <a href="./display.html#smooth-sensor-noise">Smooth Sensor Noise</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Lissage des données Libre. <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser une moyenne de 5 points pour obtenir des données Libre plus lisses.</p></div><p>Récupérer l&#39;historique du Freestyle Libre est nécessaire pour les transmetteurs BluCon. Les autres transmetteurs récupèrent automatiquement les données manquantes.</p><div class="admonition xdripitem"><p class="admonition-title">Récupérer l&#39;historique du Freestyle Libre <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Extraire l&#39;historique manqué du périphérique BluCon lors de la reconnexion au capteur.</p></div><p>L&#39;affichage Libre 1 minute est encore en développement. xDrip affiche les glycémies toutes les 5 minutes. Avec la source de données <a href="./../install/li3.html">Li3</a>, les valeurs sont enregistrées chaque minute lorsque cette option est activée.</p><div class="admonition xdripitem"><p class="admonition-title">Libre 1 minute <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Accepter les données à intervalles d&#39;une minute de Libre. Redémarrez votre téléphone pour que les modifications prennent effet.</p></div><h5 id="li3" tabindex="-1">Li3 <a class="header-anchor" href="#li3" aria-label="Permalink to &quot;Li3 {#li3}&quot;">​</a></h5><p>Les paramètres Li3 (Account ID, Official app, Smooth Li3 readings) sont expliqués sur la page <a href="./../install/li3.html#li3-settings">Li3</a>.</p><h5 id="1-min-inter-app-broadcast" tabindex="-1">1-min Inter-app broadcast <a class="header-anchor" href="#1-min-inter-app-broadcast" aria-label="Permalink to &quot;1-min Inter-app broadcast {#1-min-inter-app-broadcast}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">1-min Inter-app broadcast <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Accept data at one-minute intervals from Inter-app broadcast. Reboot your phone for changes to take effect. (accepter les données à intervalles d&#39;une minute depuis Inter-app broadcast ; redémarrez votre téléphone pour que les modifications prennent effet)</p></div><p>Accepte des valeurs toutes les minutes au lieu de toutes les 5 minutes depuis la source de données <a href="./../install/640_670.html">Inter-app broadcast</a>. Redémarrez le téléphone après avoir modifié ce réglage. Depuis le <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 sept. 2026</a>, il ne nécessite plus l&#39;Engineering mode (il s&#39;appelait auparavant &quot;640G/Eversense 1-minute&quot;).</p><p>L&#39;option ci-dessous est toujours grisée dans l&#39;application : elle ne peut pas être activée.</p><div class="admonition xdripitem"><p class="admonition-title">NE PAS UTILISER EN PRODUCTION <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',53)])])}const k=r(u,[["render",d]]);export{_ as __pageData,k as default};
